#include "conv_standard_2d_square_input_asymmetric_kernel_custom_tiling.h"
#include "register/op_def_registry.h"
#include "tiling/tiling_api.h"

namespace optiling {
const uint32_t BLOCK_DIM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ConvStandard2dSquareInputAsymmetricKernelCustomTilingData tiling;

    // x: [N, C_in, H, W]
    const gert::StorageShape* x_shape = context->GetInputShape(0);
    uint32_t n   = static_cast<uint32_t>(x_shape->GetStorageShape().GetDim(0));
    uint32_t cin = static_cast<uint32_t>(x_shape->GetStorageShape().GetDim(1));
    uint32_t inH = static_cast<uint32_t>(x_shape->GetStorageShape().GetDim(2));
    uint32_t inW = static_cast<uint32_t>(x_shape->GetStorageShape().GetDim(3));

    // w: [C_out, C_in, kH, kW]
    const gert::StorageShape* w_shape = context->GetInputShape(1);
    uint32_t cout = static_cast<uint32_t>(w_shape->GetStorageShape().GetDim(0));
    uint32_t kH   = static_cast<uint32_t>(w_shape->GetStorageShape().GetDim(2));
    uint32_t kW   = static_cast<uint32_t>(w_shape->GetStorageShape().GetDim(3));

    // Assume stride=1, padding=0, dilation=1
    uint32_t outH = inH >= kH ? (inH - kH + 1) : 0;
    uint32_t outW = inW >= kW ? (inW - kW + 1) : 0;

    uint64_t totalOut = static_cast<uint64_t>(n) * cout * outH * outW;

    context->SetBlockDim(BLOCK_DIM);

    tiling.set_n(n);
    tiling.set_cin(cin);
    tiling.set_cout(cout);
    tiling.set_inH(inH);
    tiling.set_inW(inW);
    tiling.set_kH(kH);
    tiling.set_kW(kW);
    tiling.set_outH(outH);
    tiling.set_outW(outW);
    tiling.set_totalOut(totalOut);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    context->SetTilingKey(1);
    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    // x: [N, C_in, H, W], w: [C_out, C_in, kH, kW]
    const gert::Shape* xShape = context->GetInputShape(0);
    const gert::Shape* wShape = context->GetInputShape(1);
    int64_t N   = xShape->GetStorageShape().GetDim(0);
    int64_t Cin = xShape->GetStorageShape().GetDim(1);
    int64_t H   = xShape->GetStorageShape().GetDim(2);
    int64_t W   = xShape->GetStorageShape().GetDim(3);

    int64_t Cout = wShape->GetStorageShape().GetDim(0);
    int64_t kH   = wShape->GetStorageShape().GetDim(2);
    int64_t kW   = wShape->GetStorageShape().GetDim(3);

    // stride=1, padding=0, dilation=1
    int64_t outH = H - kH + 1;
    int64_t outW = W - kW + 1;

    std::vector<int64_t> outDims = {N, Cout, outH, outW};
    gert::Shape* yShape = context->GetOutputShape(0);
    yShape->SetDimNum(4);
    for (size_t i = 0; i < outDims.size(); ++i) {
        yShape->SetDim(i, outDims[i]);
    }
    return GRAPH_SUCCESS;
}

static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
    const auto inputDataType = context->GetInputDataType(0);
    context->SetOutputDataType(0, inputDataType);
    return ge::GRAPH_SUCCESS;
}
}

