import torch
import torch.nn as nn
import torch.nn.init as init
import torch_npu
import custom_ops_lib

class ModelNew(torch.nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple):
        super().__init__()
        kh, kw = kernel_size
        # No bias, stride=1, padding=0, dilation=1, groups=1 (naive conv)
        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kh, kw))
        # Initialize like nn.Conv2d default (Kaiming uniform)
        init.kaiming_uniform_(self.weight, a=math.sqrt(5) if hasattr(torch.nn, "init") else 0.0)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return custom_ops_lib.conv_standard_2d_square_input_asymmetric_kernel_custom(x, self.weight)
