yGm.SetGlobalBuffer((__gm__ int16_t *)y + this->blockLength2 * AscendC::GetBlockIdx(), this-
>blockLength2);
zGm.SetGlobalBuffer((__gm__ int16_t *)z + this->blockLength * AscendC::GetBlockIdx(), this-
>blockLength);
if (this->tmpSize != 0) {
pipe.InitBuffer(tmpQueue, BUFFER_NUM, this->tmpSize);
}
pipe.InitBuffer(inQueueX, BUFFER_NUM, this->tileLength * sizeof(int16_t));
pipe.InitBuffer(inQueueY , BUFFER_NUM, this->tileLength2 * sizeof(int16_t));
